#include <type_traits>
struct Base {};
struct Derived : Base {};
template <typename T, size_t N> struct MyStruct { T arr[N]; };
int main() {
  MyStruct<int, 0> zero_sized_array;
  std::cout << "Size of zero-sized array: " << sizeof(zero_sized_array) << std::endl;
  std::cout << "Size of Base: " << sizeof(Base) << std::endl;
  std::cout << "Size of Derived: " << sizeof(Derived) << std::endl;
